{
  "root_causes": [
    {
      "service": "currency",
      "fault_kind": "pod_unavailable",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'norm' p, count(*) n FROM normal_traces WHERE service_name='currency' UNION ALL SELECT 'abn' p, count(*) n FROM abnormal_traces WHERE service_name='currency'", "claim": "Currency emitted 20 server spans in the normal window and zero in the abnormal window."},
        {"kind": "trace", "sql": "SELECT 'norm' p, count(*) n FROM normal_traces WHERE service_name='checkout' AND span_name LIKE '%CurrencyService%' UNION ALL SELECT 'abn' p, count(*) n FROM abnormal_traces WHERE service_name='checkout' AND span_name LIKE '%CurrencyService%'", "claim": "Checkout's CurrencyService/Convert client calls fell from 15 in normal to zero in abnormal."},
        {"kind": "metric", "sql": "SELECT count(*) n, min(value) mn, max(value) mx FROM abnormal_metrics_sum WHERE service_name='currency' AND metric='k8s.pod.uptime'", "claim": "Currency pod still reports uptime through the window, with no reset or restart, while serving no spans."}
      ]
    }
  ],
  "propagation": [
    {"from": "currency", "to": "checkout",
     "evidence": [{"kind": "trace", "sql": "SELECT span_name, attr_span_kind, count(*) n FROM abnormal_traces WHERE service_name='checkout' GROUP BY 1,2", "claim": "Checkout produced only GetCart and GetProduct client spans; no server spans or currency calls completed in the abnormal window."}]},
    {"from": "checkout", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT count(*) n, round(avg(duration)/1e6,0) avg_ms, round(max(duration)/1e6,0) max_ms FROM abnormal_traces WHERE service_name='frontend' AND span_name='POST /api/checkout'", "claim": "Frontend POST /api/checkout averaged about 213 s, max 342 s, against a few milliseconds in normal."}]},
    {"from": "frontend", "to": "frontend-proxy",
     "evidence": [{"kind": "trace", "sql": "SELECT count(*) n, round(avg(duration)/1e6,0) avg_ms FROM abnormal_traces WHERE service_name='frontend-proxy' AND span_name='ingress' AND attr_http_response_status_code=504", "claim": "Frontend-proxy ingress returned 504 after about 15 s for user requests stalled behind checkout."}]}
  ]
}

